package com.sumedha.commerce.auth.security;
import com.sumedha.commerce.auth.config.AuthProperties; import com.sumedha.commerce.auth.entity.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.junit.jupiter.api.Test; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class JwtServiceTest { private static final String SECRET="12345678901234567890123456789012"; private final JwtService jwt=new JwtService(new AuthProperties(SECRET,Duration.ofMinutes(5),Duration.ofDays(1),"test-issuer"));
 @Test void generatedTokenHasExpectedClaims(){User user=new User("customer@example.test","hash");String token=jwt.create(user);assertFalse(token.isBlank());Claims claims=jwt.parse(token).getPayload();assertEquals(user.getId().toString(),claims.getSubject());assertEquals("CUSTOMER",claims.get("role"));assertEquals("test-issuer",claims.getIssuer());assertNotNull(claims.getIssuedAt());assertNotNull(claims.getExpiration());assertTrue(claims.getExpiration().after(claims.getIssuedAt()));}
 @Test void rejectsMalformedExpiredOtherKeyAndIssuer(){assertThrows(JwtException.class,()->jwt.parse("not-a-jwt"));String expired=Jwts.builder().subject("u").issuer("test-issuer").issuedAt(Date.from(Instant.now().minusSeconds(120))).expiration(Date.from(Instant.now().minusSeconds(60))).signWith(Keys.hmacShaKeyFor(SECRET.getBytes())).compact();assertThrows(JwtException.class,()->jwt.parse(expired));String wrongKey=Jwts.builder().subject("u").issuer("test-issuer").expiration(Date.from(Instant.now().plusSeconds(60))).signWith(Keys.hmacShaKeyFor("abcdefghijabcdefghijabcdefghijabcdef".getBytes())).compact();assertThrows(JwtException.class,()->jwt.parse(wrongKey));String wrongIssuer=Jwts.builder().subject("u").issuer("other").expiration(Date.from(Instant.now().plusSeconds(60))).signWith(Keys.hmacShaKeyFor(SECRET.getBytes())).compact();assertThrows(JwtException.class,()->jwt.parse(wrongIssuer));}
 @Test void rejectsShortSecret(){assertThrows(IllegalStateException.class,()->new JwtService(new AuthProperties("short",Duration.ofMinutes(1),Duration.ofDays(1),"issuer")));}}
